// Ergebnis der Salesforce-Suche auswerten
const hits = $input.all();
const first = hits.length > 0 ? hits[0].json : null;
const found = first && first.Id;

if (found) {
  const c = first;
  return [{
    json: {
      is_bestandskunde: true,
      contact_id: c.Id,
      account_id: c.AccountId || null,
      name: c.Name || null,
      account_name: c.Account ? c.Account.Name : null,
      email: c.Email || null,
      spoken_response: `Willkommen zurueck, ${c.FirstName || c.Name || ''}. Ich habe Sie als Bestandskunde gefunden.`
    }
  }];
}

return [{
  json: {
    is_bestandskunde: false,
    contact_id: null,
    account_id: null,
    name: null,
    spoken_response: 'Ich konnte Sie nicht als Bestandskunde finden. Moechten Sie sich als Neukunde erfassen lassen?'
  }
}];

