const b = ($json.body) || {};
if (!b.contact_id) { throw new Error('contact_id fehlt fuer update_contact'); }
const fields = {};
const set = (k, v) => { if (v !== undefined && v !== null && v !== '') fields[k] = v; };
set('Email', b.email);
set('Phone', b.new_phone);
set('MobilePhone', b.new_mobile);
set('MailingStreet', b.street);
set('MailingCity', b.city);
set('MailingPostalCode', b.zip);
return [{ json: { contact_id: b.contact_id, fields } }];

const raw = ($json.body && $json.body.phone) ? String($json.body.phone).trim() : '';
let s = raw.replace(/[^\d+]/g, '');
let nsn = s;
if (nsn.indexOf('+49') === 0) nsn = nsn.slice(3);
else if (nsn.indexOf('0049') === 0) nsn = nsn.slice(4);
else if (nsn.indexOf('49') === 0 && nsn.length > 10) nsn = nsn.slice(2);
else if (nsn.indexOf('0') === 0) nsn = nsn.slice(1);
const set = new Set();
if (raw) set.add(raw);
if (s) set.add(s);
if (nsn) { set.add('+49' + nsn); set.add('0049' + nsn); set.add('0' + nsn); set.add('49' + nsn); set.add(nsn); }
const list = Array.from(set).filter(Boolean).map(function(v){ return "'" + v.replace(/'/g, '') + "'"; }).join(', ');
const query = "SELECT Id, FirstName, LastName, Name, Phone, MobilePhone, Email, AccountId, Account.Name FROM Contact WHERE Phone IN (" + list + ") OR MobilePhone IN (" + list + ") LIMIT 1";
return [{ json: { body: $json.body, query: query, candidates: Array.from(set) } }];

