## Placetel AI function call

Paste this JSON into the Placetel AI function editor. The operation is selected via the `operation` field.

{
  "type": "function",
  "name": "salesforce-crm",
  "description": "Zentrale Schnittstelle zum Salesforce-CRM für telefonische Anliegen. ",
  "parameters": {
    "type": "object",
    "properties": {
      "vorgang": {
        "type": "string",
        "enum": [
          "bestandskunde_pruefen",
          "lead_anlegen",
          "rueckruf_erfassen",
          "ticket_anlegen",
          "kontakt_aktualisieren"
        ],
        "description": "Der auszuführende Vorgang. Bestimmt, welche weiteren Felder benötigt werden."
      },
      "phone": {
        "type": "string",
        "description": "Telefonnummer des Anrufers, international (+49...). Für bestandskunde_pruefen, rueckruf_erfassen, lead_anlegen und zur Verknüpfung bei ticket_anlegen."
      },
      "email": {
        "type": "string",
        "description": "E-Mail des Anrufers. Optional bei lead_anlegen; bei kontakt_aktualisieren = neue E-Mail."
      },
      "first_name": {
        "type": "string",
        "description": "Vorname. Optional bei vorgang=lead_anlegen."
      },
      "last_name": {
        "type": "string",
        "description": "Nachname. Pflicht bei vorgang=lead_anlegen."
      },
      "company": {
        "type": "string",
        "description": "Firmenname. Optional bei vorgang=lead_anlegen."
      },
      "name": {
        "type": "string",
        "description": "Name des Anrufers. Optional bei vorgang=rueckruf_erfassen."
      },
      "reason": {
        "type": "string",
        "description": "Grund des Rückrufs. Optional bei vorgang=rueckruf_erfassen."
      },
      "preferred_time": {
        "type": "string",
        "description": "Gewünschte Rückrufzeit als Freitext, z. B. morgen vormittag. Optional bei vorgang=rueckruf_erfassen."
      },
      "subject": {
        "type": "string",
        "description": "Kurzer Betreff. Pflicht bei vorgang=ticket_anlegen."
      },
      "description": {
        "type": "string",
        "description": "Ausführliche Beschreibung. Pflicht bei vorgang=ticket_anlegen."
      },
      "case_type": {
        "type": "string",
        "enum": [
          "Other",
          "Question",
          "Problem"
        ],
        "description": "Art des Falls. Optional bei vorgang=ticket_anlegen (Standard Other)."
      },
      "priority": {
        "type": "string",
        "enum": [
          "High",
          "Medium",
          "Low"
        ],
        "description": "Priorität. Optional bei vorgang=ticket_anlegen."
      },
      "contact_id": {
        "type": "string",
        "description": "Salesforce-Kontakt-ID (aus bestandskunde_pruefen). Pflicht bei vorgang=kontakt_aktualisieren."
      },
      "new_phone": {
        "type": "string",
        "description": "Neue Telefonnummer. Optional bei vorgang=kontakt_aktualisieren."
      },
      "new_mobile": {
        "type": "string",
        "description": "Neue Mobilnummer. Optional bei vorgang=kontakt_aktualisieren."
      },
      "street": {
        "type": "string",
        "description": "Neue Straße. Optional bei vorgang=kontakt_aktualisieren."
      },
      "city": {
        "type": "string",
        "description": "Neuer Ort. Optional bei vorgang=kontakt_aktualisieren."
      },
      "zip": {
        "type": "string",
        "description": "Neue PLZ. Optional bei vorgang=kontakt_aktualisieren."
      }
    },
    "required": [
      "vorgang"
    ]
  }
}
